mapper.select:
SELECT id, tenant_code, session_id, session_no, agent_id, message_id, message_seq,
       rule_id, rule_name, rule_type, severity, hit_keyword, snippet, advice,
       status, handler_id, handle_remark, handle_time,
       create_time, update_time, creator, editor, is_deleted
  FROM qa_alert
 WHERE tenant_code = #{tenantCode}
   AND is_deleted = FALSE

   AND status = #{status}


   AND severity = #{severity}


   AND rule_type = #{ruleType}


   AND session_no = #{sessionNo}


   AND (session_no ILIKE '%' || #{keyword} || '%'
        OR rule_name ILIKE '%' || #{keyword} || '%'
        OR hit_keyword ILIKE '%' || #{keyword} || '%'
        OR snippet ILIKE '%' || #{keyword} || '%')


   AND create_time >= #{startTime}


   AND create_time <= #{endTime}

 ORDER BY create_time DESC
 LIMIT #{limit}
